{
  "schemaVersion": "0.2",
  "slug": "tabs",
  "name": "Tabs",
  "status": "experimental",
  "purpose": "Organizes content into a set of selectable tab panels.",
  "scenarios": [
    "Switch between settings sections",
    "Browse content categories without leaving the page",
    "Use arrow keys to move between tabs in RTL"
  ],
  "props": {
    "items": {
      "type": "string",
      "required": true,
      "description": "Array of tabs with value, label, and content."
    },
    "defaultValue": {
      "type": "string",
      "required": false,
      "description": "Uncontrolled initial tab value."
    },
    "value": {
      "type": "string",
      "required": false,
      "description": "Controlled active tab value."
    },
    "onChange": {
      "type": "event",
      "required": false,
      "description": "Receives the next active tab value."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "A tab is active and its panel is visible."
    }
  ],
  "composition": {
    "allowedParents": [
      "dialog",
      "app-shell",
      "page"
    ],
    "allowedChildren": [
      "text",
      "input",
      "button"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not nest tabs inside tabs.",
    "Do not use tabs when the content should be visible at once."
  ],
  "a11y": {
    "role": "tablist",
    "keyboard": [
      "Tab moves to the active tab",
      "Arrow keys move between tabs",
      "Tab moves into the tab panel"
    ],
    "focus": "Visible focus indicator on tab triggers; roving tabindex is handled by the primitive.",
    "labeling": "Each tab is labelled by its visible text; each panel is associated with its tab.",
    "wcag": [
      "1.3.1",
      "2.1.1",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Tab list scrolls horizontally when it overflows. Active tab stays visible.",
    "breakpoints": {
      "compact": "Tab list may overflow horizontally; users can swipe/scroll.",
      "medium": "Tab list fits the available width.",
      "large": "Tab list fits the available width."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only. Tab order follows the document direction; arrow-key roving is handled by the primitive.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "tabs",
    "states": [
      "active"
    ],
    "intents": [
      "switch-view"
    ]
  }
}

.cu-tabs {
  display: flex;
  flex-direction: column;
}

.cu-tabs__list {
  display: flex;
  gap: var(--cu-space-1);
  border-block-end: 1px solid var(--cu-color-border-default);
  margin-block-end: var(--cu-space-2);
}

.cu-tabs__trigger {
  min-block-size: 2.75rem;
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-3);
  border: none;
  border-block-end: 2px solid transparent;
  background: transparent;
  color: var(--cu-color-fg-default);
  font: inherit;
  cursor: pointer;
}

.cu-tabs__trigger:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

.cu-tabs__trigger[data-state='active'] {
  border-block-end-color: var(--cu-color-palette-brand);
  color: var(--cu-color-palette-brand);
  font-weight: 700;
}

.cu-tabs__content {
  padding-block: var(--cu-space-2);
  padding-inline: var(--cu-space-1);
  color: var(--cu-color-fg-default);
}

@media (prefers-reduced-motion: reduce) {
  .cu-tabs__trigger {
    transition-duration: 0.01ms;
  }
}

import { TabsPrimitive } from '@chameleon-ui/primitives'
import type { ReactNode } from 'react'
import './styles.css'

export interface TabItem {
  value: string
  label: string
  content: ReactNode
}

export interface TabsProps {
  items: TabItem[]
  defaultValue?: string
  value?: string
  onChange?: (value: string) => void
  className?: string
}

export function Tabs({ items, defaultValue, value, onChange, className }: TabsProps) {
  const classes = ['cu-tabs', className].filter(Boolean).join(' ')

  return (
    <TabsPrimitive.Root
      className={classes}
      data-ai-role="tabs" data-ai-intent="switch-view"
      data-ai-state={value ?? defaultValue ?? items[0]?.value ?? 'default'}
      defaultValue={defaultValue}
      value={value}
      onValueChange={(details) => onChange?.(details.value)}
    >
      <TabsPrimitive.List className="cu-tabs__list">
        {items.map((item) => (
          <TabsPrimitive.Trigger
            key={item.value}
            className="cu-tabs__trigger"
            value={item.value}
          >
            {item.label}
          </TabsPrimitive.Trigger>
        ))}
      </TabsPrimitive.List>
      {items.map((item) => (
        <TabsPrimitive.Content key={item.value} className="cu-tabs__content" value={item.value}>
          {item.content}
        </TabsPrimitive.Content>
      ))}
    </TabsPrimitive.Root>
  )
}
